"""Question bank. Six unique questions per lecture; five correct answers defeat the enemy."""
def make_questions():
    bank={}
    def add(l,topic,q,code,options,answer,why):
        bank.setdefault(l,[]).append(dict(id=f'{l}-{len(bank.get(l,[]))+1}',topic=topic,q=q,code=code,options=options,answer=answer,why=why))
    add(1,'1.6','Какое значение получает x?','int x{};',['0','Значение не задано','Ошибка компиляции'],0,'Пустая list-initialization для int приводит к value-initialization и нулевому значению.')
    add(1,'1.6','Допустима ли эта инициализация?','int x{3.14};',['Да, получится 3','Да, получится 4','Нет, ошибка компиляции'],2,'Фигурные скобки запрещают narrowing double в int. При int x = 3.14 дробная часть была бы отброшена.')
    add(1,'1.6','Что создаёт это объявление?','std::string name();',['Пустую строку','Функцию, возвращающую string','Массив строк'],1,'Это объявление функции. Чтобы создать объект без аргументов, можно написать std::string name{};.')
    add(1,'1.6','Какие элементы окажутся в v?','std::vector<int> v{3, 7};',['Три семёрки','Два элемента: 3 и 7','Три нуля'],1,'Здесь непустой список в {} выбирает initializer_list-конструктор. Запись v(3,7) создала бы три семёрки.')
    add(1,'1.6','Каков результат чтения x в C++20?','int main() {\n    int x;\n    std::cout << x;\n}',['Всегда 0','Всегда ошибка компиляции','UB: определённого вывода нет'],2,'Неинициализированный автоматический int нельзя читать до присваивания. Само объявление допустимо.')
    add(1,'1.8','Что напечатает программа?','int a = 5, b = 2;\ndouble x = a / b;\nstd::cout << x;',['2','2.5','3'],0,'Деление выполнено для двух int, его результат 2. Последующее преобразование в double не восстанавливает дробную часть.')
    add(2,'2.3','Что произойдёт при p == nullptr?','if (p && *p > 0) { /* ... */ }',['Возникнет разыменование nullptr','Правая часть && не вычислится','Ошибка компиляции'],1,'У встроенного && есть короткое замыкание. Нулевой указатель даёт false, поэтому *p не вычисляется.')
    add(2,'2.4','Что напечатает код?','int x=4;\nint old=x++;\nint now=++x;\nstd::cout << x << " " << old << " " << now;',['6 4 6','5 4 5','6 5 6'],0,'Постфиксный ++ возвращает прежнее значение 4 и меняет x на 5. Префиксный ++ меняет x на 6 и даёт 6.')
    add(2,'2.1','Каково поведение signed-переполнения?','int x = std::numeric_limits<int>::max();\nx += 1;',['Определённый переход к минимуму','UB','x не изменится'],1,'Переполнение знакового int — undefined behavior. Модульная арифметика гарантируется для unsigned, но не для signed.')
    add(2,'2.12','Приоритет определяет порядок вызова f и g?','int value = f() + g();',['Всегда f, затем g','Всегда g, затем f','Нет, + не задаёт такого порядка'],2,'Приоритет задаёт группировку. Для операндов + нельзя обещать порядок f перед g.')
    add(2,'2.7','Что значит false у выражения input >> x?','int x{};\nif (!(input >> x)) { /* ... */ }',['Ввод не удался, поток в состоянии ошибки','x обязательно равен нулю','Поток автоматически закрыт'],0,'Поток преобразуется к bool с учётом состояния. При неудачном чтении нужно обработать ошибку, а не считать ввод успешным.')
    add(2,'2.12','Каким будет результат сравнения?','int n = -1;\nunsigned u = 1;\nstd::cout << (n < u);',['1','0','Ошибка компиляции'],1,'При int и unsigned int одинакового ранга n преобразуется к unsigned. Значение становится большим положительным, поэтому сравнение ложно.')
    add(3,'3.4','Какая операция запрещена?','int x=1, y=2;\nconst int* p=&x;',['p = &y;','*p = 3;','p = nullptr;'],1,'const относится к объекту по адресу. Указатель можно перенаправлять, но менять int через него нельзя.')
    add(3,'3.12','Передаёт ли get() владение?','auto owner=std::make_unique<int>(7);\nint* observer=owner.get();',['Да, теперь observer владелец','Нет, owner продолжает владеть','Создаётся копия int'],1,'get() возвращает невладеющий указатель. После owner.reset() такой observer может стать висячим.')
    add(3,'3.13','Можно ли присвоить v[0] после reserve?','std::vector<int> v;\nv.reserve(10);\n// v[0] = 1;',['Да, reserve создал десять элементов','Нет, size всё ещё равен нулю','Можно только читать v[0]'],1,'reserve меняет ёмкость, но не создаёт элементы. resize(10) увеличил бы размер до десяти.')
    add(3,'3.3','Можно ли разыменовать end?','int a[3]{1,2,3};\nint* end = a + 3;',['Да, это последний элемент','Нет, это адрес за последним элементом','Да, получится 0'],1,'Указатель one-past-end разрешено сформировать, но разыменовывать его нельзя.')
    add(3,'3.9','Какую перегрузку выбирает f(r)?','void f(int&);\nvoid f(int&&);\nint&& r = 1;\nf(r);',['f(int&)','f(int&&)','Неоднозначность'],0,'Именованная r в выражении является lvalue. Объявленный ссылочный тип сам по себе не делает использование имени rvalue.')
    add(3,'3.14','Безопасна ли ссылка после точки с запятой?','const std::string& pass(const std::string& s){return s;}\nconst std::string& r = pass(std::string{"hi"});',['Да, до конца жизни r','Нет, временная строка уже уничтожена','Создана независимая копия'],1,'Возвращение ссылки не передаёт продление времени жизни. Временный аргумент уничтожается в конце полного выражения с вызовом.')
    add(4,'4.2','Чему станет равен n?','void f(int x){ x=9; }\nint n=1; f(n);',['9','1','Неопределённому значению'],1,'Передача по значению создаёт отдельный параметр. Изменение x не меняет n.')
    add(4,'4.11','Как передать строку для изменения исходного объекта?','// Сигнатура функции rename',['void rename(std::string);','void rename(const std::string&);','void rename(std::string&);'],2,'Неконстантная ссылка позволяет изменить исходную строку. Значение создаёт копию, const-ссылка ограничивает изменение.')
    add(4,'4.3','Какая перегрузка выбрана?','void f(int);\nvoid f(double);\nf(1);',['f(int)','f(double)','Ошибка неоднозначности'],0,'Точное совпадение int лучше преобразования в double.')
    add(4,'4.12','Корректен ли вызов?','void f(int,double);\nvoid f(double,int);\nf(1,1);',['Да, первый кандидат','Да, второй кандидат','Нет, неоднозначность'],2,'Каждый кандидат лучше по одному из аргументов. Единственного лучшего кандидата нет.')
    add(4,'4.13','Что безопасно вернуть из make?','std::string make() {\n    std::string local="Ada";\n    return local;\n}',['Значение, как в примере','Только ссылку на local','Только указатель на local'],0,'Возврат по значению даёт самостоятельный результат; ссылки и указатели на local после выхода стали бы висячими.')
    add(4,'4.7','Гарантировано ли NRVO?','T make(){ T local; return local; }',['Да, во всех случаях C++20','Нет, NRVO необязательно','Возврат локального объекта всегда запрещён'],1,'NRVO именованной локальной переменной необязательно. Гарантированная copy elision для подходящего prvalue — другой случай.')
    add(5,'5.1','Какой доступ у value?','class Box {\n    int value{};\n};',['public','protected','private'],2,'У class доступ к членам по умолчанию private. У struct по умолчанию public.')
    add(5,'5.12','Что лучше сохраняет инвариант balance >= 0?','// Выбираем интерфейс Account',['Публичный int balance','Метод withdraw с проверкой до изменения','Геттер int& balance()'],1,'Проверяемая операция ограничивает изменение допустимыми состояниями. Публичное поле или изменяемая ссылка позволяют обойти проверки.')
    add(5,'5.5','Можно ли вызвать get для const-объекта?','struct Box { int get(){return 1;} };\nconst Box b{};\nb.get();',['Да','Нет, метод не const','Да, потому что результат int'],1,'Неконстантный метод не вызывается для const-объекта. Const-квалификатор относится к объекту вызова, а не к возвращаемому типу.')
    add(5,'5.6','Есть ли this у static-метода?','class Counter {\npublic: static int count();\n};',['Да, тип Counter*','Да, тип const Counter*','Нет'],2,'Статический метод не связан с неявным текущим объектом. Для доступа к обычным полям нужен явно заданный объект.')
    add(5,'5.7','Дружественная свободная функция — метод?','class Box {\n    friend void print(const Box&);\n};',['Да, получает this','Нет, получает только особый доступ','Да, становится static-методом'],1,'friend даёт доступ к закрытым членам, но не превращает свободную функцию в метод.')
    add(5,'5.13','Может ли const-метод менять внешний int?','struct View {\n    int* p;\n    void set(int n) const { *p=n; }\n};',['Да, если p указывает на живой изменяемый int','Нет, const делает всё по адресам константным','Только если p объявлен mutable'],0,'Поле-указатель не меняется; меняется отдельный объект по адресу. Const не распространяется автоматически на него.')
    add(6,'6.12','Что вызывается при создании b?','T a;\nT b = a;',['Copy constructor','Copy assignment','Move assignment'],0,'b создаётся из lvalue a. Знак = в объявлении не означает присваивание уже существующему объекту.')
    add(6,'6.2','Какой порядок инициализации?','struct S {\n int x; int y;\n S(): y(2), x(1) {}\n};',['Сначала y, затем x','Сначала x, затем y','Зависит от оптимизации'],1,'Порядок задаётся объявлением полей в классе, а не списком инициализации.')
    add(6,'6.14','Вызывается ли ~Service при исключении из его конструктора?','struct Service {\n Resource r;\n Service(){throw Error{};}\n ~Service();\n};',['Да, обязательно','Нет, но уже созданное r будет разрушено','Ничего вообще не разрушается'],1,'Сам Service не был полностью построен, его деструктор не вызывается. Полностью созданные поля и базы уничтожаются.')
    add(6,'6.11','Какая операция обычно подходит к std::move(a)?','const T a;\nT b = std::move(a);\n// Доступны T(const T&) и T(T&&)',['T(T&&)','T(const T&)','Обе обязательно вызываются'],1,'std::move сохраняет const. const T&& не подходит к T&&, но может связаться с const T& для копирования.')
    add(6,'6.10','Что означает Rule of Zero?','class Scores { std::vector<int> values; };',['Нельзя иметь конструкторы','Не писать свои специальные операции, когда поля управляют ресурсами','Никогда не использовать динамическую память'],1,'RAII-поля уже обеспечивают управление ресурсами. Собственные деструктор/copy/move обычно не нужны; обычные конструкторы допустимы.')
    add(6,'6.12','Выполнится ли запасное копирование?','struct T {\n T(const T&)=default;\n T(T&&)=delete;\n};\n// T b=std::move(a);',['Да, удалённый move игнорируется','Нет, выбранный удалённый move даёт ошибку','Зависит только от размера T'],1,'Явно удалённая функция участвует в выборе перегрузки. Если она лучшая, ошибка не заменяется переходом к второй лучшей.')
    add(7,'7.2','Что обычно возвращает operator+=?','T& operator+=(const T& rhs);',['Ссылку на изменённый *this','Ссылку на локальную копию','Старое значение'],0,'+= меняет левый операнд и обычно возвращает *this по ссылке для цепочек операций.')
    add(7,'7.3','Зачем int у постфиксного ++?','T operator++(int);',['Это число прибавляемых единиц','Это маркер для отличия постфиксной формы','Это тип результата'],1,'Фиктивный int отличает постфиксный оператор от префиксного T& operator++().')
    add(7,'7.12','Можно ли вернуть ссылку на local?','T& operator+(const T& a,const T& b){\n T local;\n return local;\n}',['Нет, результат станет висячим','Да, return продлевает lifetime','Да, если объявить local const'],0,'Локальный объект уничтожается при выходе из функции. Обычный operator+ должен вернуть самостоятельное значение.')
    add(7,'7.5','Какой результат подходит для цепочки вывода?','std::cout << a << b;',['void','std::ostream&','Копия std::ostream'],1,'Возврат ссылки на тот же поток позволяет следующему << продолжить вывод.')
    add(7,'7.6','Какая const-перегрузка сохраняет запрет записи?','// Контейнер хранит int elements[2]',['int& operator[](std::size_t) const;','const int& operator[](std::size_t) const;','void operator[](std::size_t) const;'],1,'Константная ссылка разрешает чтение элемента и запрещает запись через результат этого обращения.')
    add(7,'7.13','Зачем читать компоненты во временные переменные?','int x{},y{};\nif(in >> x >> y){ p.x=x; p.y=y; }',['Чтобы при неудаче сохранить p прежним','Чтобы автоматически откатить вход потока','Чтобы отключить ошибки ввода'],0,'p меняется только после полного успешного чтения. Сам поток мог прочитать часть входа и остаётся в состоянии ошибки.')
    add(8,'8.15','Какой результат виртуального вызова?','struct B {virtual int f() const{return 1;}};\nstruct D:B {int f() const override{return 2;}};\nD d; const B& b=d;\nstd::cout << b.f();',['1','2','Ошибка компиляции'],1,'Ссылка обращается к живому D, срезки нет. Виртуальная диспетчеризация выбирает D::f.')
    add(8,'8.6','А если создать b по значению?','struct B {virtual int f() const{return 1;}};\nstruct D:B {int f() const override{return 2;}};\nD d; B b=d;\nstd::cout << b.f();',['1','2','UB при самом копировании'],0,'b — самостоятельный B. Произошла срезка; виртуальность не восстанавливает производную часть.')
    add(8,'8.5','Какая f будет выбрана?','struct B {void f(double);};\nstruct D:B {void f(int);};\nD d; d.f(2.5);',['B::f(double)','D::f(int)','Всегда ошибка'],1,'Имя f в D скрывает базовый набор перегрузок. using B::f; позволило бы участвовать и базовой функции.')
    add(8,'8.17','Какой метод вызывается в конструкторе Base?','struct Base {\n Base(){ f(); }\n virtual void f();\n};\n// Derived переопределяет f',['Derived::f','Base::f','Случайная реализация'],1,'Во время конструктора Base виртуальный вызов относится к текущему конструируемому классу. Производная часть ещё не готова.')
    add(8,'8.11','Кто инициализирует общую виртуальную базу?','struct B: virtual A {};\nstruct C: virtual A {};\nstruct D: B,C {};',['Всегда B','Всегда C','Наиболее производный класс D'],2,'При создании D виртуальную базу A инициализирует D. Для самостоятельного B эту роль выполнял бы B.')
    add(8,'8.17','Что нужно для обычного удаления Derived через Base*?','Base* p = new Derived;\ndelete p;',['Подходящий виртуальный деструктор Base','Только любой virtual-метод','Ничего, всегда корректно'],0,'В обычном полиморфном удалении базе нужен виртуальный деструктор. Виртуальность других методов не делает его виртуальным автоматически.')
    assert len(bank)==8 and all(len(q)==6 for q in bank.values())
    return bank
